    let mut score = post_residual as f64 * 1.05;

    // 1. Enhanced Fragmentation Penalty:
    // Targeting "dead zones" (1-19). Increased penalty intensity to force items into 
    // larger gaps or empty bins instead of creating slivers.
    if post_residual > 0 && post_residual <= 19 {
        score += 65.0 - (post_residual as f64 * 0.4);
    }

    // 2. Adaptive Lookahead:
    // Reward bins that leave exactly enough for the next item, while heavily 
    // penalizing "near-misses" (1-14) that create unusable residual space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let remaining = post_residual - next_item_size;
        if remaining == 0 {
            score -= 52.0; 
        } else if remaining < 15 {
            score += 35.0; 
        } else {
            score -= (next_item_size as f64) * 0.92;
        }
    }

    // 3. Harmonic Modulo Pressure:
    // Focus on divisors of 100 to maximize potential for future perfect fits.
    if post_residual > 0 && (post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual == 33) {
        score -= 22.0;
    }

    // 4. Scarcity/Open Bin Control:
    // High-priority forced-fit to prevent unnecessary expansion.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 60.0 / (fitting_bins_count as f64);
    }

    // 5. New Bin Logic:
    // Non-linear penalty for new bins using stream progress and bin saturation.
    if bin_residual == bin_capacity {
