pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (residual gaps too small for any likely item).
    // If post_residual is < 10, it is likely unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Penalize opening new bins if there are existing fitting bins.
    // We heavily bias against opening a new bin unless the fit is perfect (0 residual).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 80.0;
    }

    // 3. Lookahead synergy: If next_item_size fits in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 4. Global pressure: As we near the end of the stream, favor finishing bins (low residual).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 15 {
        score -= 10.0;
    }

    // 5. Penalize creating many open bins (fragmentation).
    // Only apply if we aren't opening a new bin (i.e., bin_residual < bin_capacity).
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    }

    // 6. Prefer bins where the post_residual is closer to the mean_residual of other bins
    // to maintain uniformity of bin states.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We introduce a non-linear penalty for creating small, unusable gaps.
    // Small gaps (post_residual < 10) are extremely likely to be wasted.
    let gap_penalty = if post_residual < 10 && post_residual > 0 {
        25.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Lookahead interaction: If the next item is large, avoid leaving tiny residuals.
    // If next_item_size is large, we want post_residual to be >= next_item_size.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_res) * 0.8
    } else {
        0.0
    };

    // Stream progression coupling: As we approach the end of the stream, 
    // prioritize closing existing bins (lower mean_residual) to keep density high.
    let density_pressure = (mean_residual - post_res) * progress;

    // New bin bias: If this is an empty bin (bin_residual == bin_capacity), 
    // only choose it if the penalty for fitting into existing bins is high.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_base = if is_new_bin {
        // Only open new bins if we have many open bins already or 
        // to avoid very poor fits in existing bins.
        15.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Calculate final score. Lower is better.
    // We favor bins that leave enough room for the next item or leave a perfect fit.
    let mut score = post_res + gap_penalty + lookahead_penalty + density_pressure + new_bin_base;

    // Strongly penalize opening a new bin if the item could fit well into an existing one.
    if is_new_bin && fitting_bins_count > 0 {
        score += 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are too small to fit common future items (Dead Space)
    // We treat residuals < 10 as "dead" unless it's a perfect fit (0)
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Use lookahead to discourage leaving a bin with a residual smaller than the next item
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Favor bins that align with the global mean residual to keep distribution uniform
    let balance_score = (post - mean_residual).abs() * 0.5;

    // As the stream progresses, increase the cost of opening new bins 
    // (fitting_bins_count == 0 implies a new bin is being evaluated)
    let new_bin_penalty = if fitting_bins_count == 0 {
        20.0 + (progress * 30.0) 
    } else {
        0.0
    };

    // Combine into a non-linear objective function
    // Lower score is better. We prioritize small post_residual (Best Fit) 
    // but modulate by the penalties derived above.
    let mut score = post + dead_space_penalty + lookahead_penalty + balance_score + new_bin_penalty;

    // Apply a non-linear scaling factor based on how many bins are already open
    // to discourage excessive fragmentation as the stream progresses.
    score *= 1.0 + (open_bins_count as f64 * 0.01 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual). 
    // We heavily penalize creating "unusable" residuals (gaps < 10, since min item size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Harmonic Modulo Pressure: Penalize residuals that are not multiples of common item 
    // divisors, as they often lead to stranded space.
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    // 4. Scarcity/Open Bin Control: If this is the only fitting bin, reduce its score 
    // to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // 5. New Bin Logic: If we are considering a new bin (bin_residual == bin_capacity),
    // only accept it if the current mean_residual is already very tight (indicating 
    // high fragmentation) or we are forced to.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalize new bin creation based on average fragmentation of existing bins.
            score = 45.0 + (mean_residual * 0.5);
        }
    }

    // 6. Progressive Scaling: As the stream nears completion, become more aggressive 
    // about packing into existing bins to minimize total bins opened.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (fragments too small for common items)
    // We penalize post_residual values that are likely to be unusable (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead: If next_item_size is large, favor keeping larger residuals (smaller post_residual)
    if next_item_size > 0 {
        let next_fit_penalty = if post_residual < next_item_size { 25.0 } else { 0.0 };
        score += next_fit_penalty * (1.0 - progress);
    }

    // New Bin Logic:
    // If we are forced to open a new bin, we only do so if the current fitting options are poor.
    if is_new_bin {
        // Only consider a new bin if the existing fit is very poor (e.g., high post_residual)
        // We scale this threshold by progress to be more conservative as we approach the end
        let threshold = 20.0 + (30.0 * progress);
        score = threshold; 
    } else {
        // Reward filling bins that are already partially full to consolidate usage
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;

        // Penalize opening too many bins early on
        score += (open_bins_count as f64) * (0.5 * (1.0 - progress));
    }

    // Favor bins that align with the global mean, reducing variance in bin utilization
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize Best Fit (smaller post_residual is better)
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that is too small for common items (e.g., < 15)
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // Lookahead logic: if the next item can fit in the current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Global state awareness: if we are late in the stream, be more aggressive about filling bins
    // to avoid leaving too many sparsely filled bins at the end.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // New bin logic: if this is a new bin (bin_residual == bin_capacity), 
    // penalize opening it unless we have no other good options.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early
        score += 60.0;
        // Reduce penalty if we have many open bins already or if fitting_bins_count is low
        score -= (open_bins_count as f64 * 2.0);
    }

    // If this is the last chance to fit into an existing bin, reward it to keep the count low
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Adjust based on mean_residual: avoid bins that deviate too much from the current average
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
